INSERT INTO `biding_package` (`packid`, `title`, `amount`, `package_valid`, `description`, `r_earn`, `total_member`, `addonkey_amount`, `addonarea_amount`, `pimage`, `noofarea`, `noofkey`, `topupamount`, `minamount`, `ratio`) VALUES
(1, 'TRIAL PACKAGE                                            ', '10', 365, '<p>*TRIAL PACKAGE*<br />*CALLINFO* will Provide the Online Facility to the Outlets Vendor Services with the Following Terms and Conditions.</p>\r\n<p>For the use of this Service fee of 365 Days 430/- Inclusive Services Tax 18%<br />If U Need To Add - On Area Services (or) Add -On Keyword , Extra will Apply.<br />In This SILVER Package , You Get Free&nbsp; SINGLE Listing of 1 Keyword + 10 Areas as Default (OR) 2 Keywords + 5 Areas as Default, Based in Your Convenience.&nbsp;<br />Directory Listing Keyword Wise Wallet Addon Rs.1000/- In This Package, Per Lead&nbsp;you get&nbsp;&nbsp;Rs.100/- Debited&nbsp; From Your Wallet.<br />You Have to&nbsp; Maintain Rs.100/- as&nbsp; Minimum Balance in Your Wallet , Only Then You will be Able to do&nbsp; Bidding and&nbsp; The Lead Generation will take Place.&nbsp;<br />Add on Keyword Rs.2500 &amp; Areas Rs.3500 Chargeable</p>\r\n<p>Basic Setup Charge Includes the Following Works<br />Set up your Service Outlet &amp; Directory Listing Including Contact Information on the Services Portal<br />100% Control by the Lead Management, Service Outlets with Our CMS&nbsp;that You Can Regulate Each &amp; Everything by Yourself.<br />Upon the Cessation of the Services &amp; Directory Listing Outlets, the Contract is Void. With removal of the Services &amp; Directory Outlets, the Contract is Further Transferred to the New Premises with all Right and Obligation, Changes Shall be Notified Immediately<br />Top-up&nbsp;Your Wallet Amount Online Also.</p>\r\n<p>*Terms &amp; Condition*:</p>\r\n<p>Degradation or Upgradation of any Service Bidding Outlets Automatically it will be Activated Within Few Mins.<br />If You have Any Changes you Can Feel Free to Contact Our Customer Care + 73055 88891<br />Support Timing Morning 10.00 am to 6.30 pm Only</p>', 10, 1, 2500, 3500, '', 10, 1, 430, 100, '50'),
(2, 'BUSINESS COMBO OFFER                      ', '10000', 365, '<p><strong><br />CALLINFO</strong> will Provide the Online Facility to the Outlets Vendor Services with the Following Terms and Conditions.</p>\r\n<ol>\r\n<li>For the use of this Service fee of 365 Days <strong>100</strong><strong>00/- </strong>Inclusive Services Tax18%</li>\r\n<li>If U Need To Add - On Area Services (or) Add -On Keyword , Extra Charges will Apply.&nbsp;</li>\r\n<li>In This Gold Package, You Get <strong>Free Listing of 3 Keywords + 10 Areas&nbsp; as Default</strong></li>\r\n<li>Directory Listing Keyword Wise Wallet Addon Rs.7500/- This Packages, <strong>Per Lead </strong>you get&nbsp; <strong>Rs.100/- Debited&nbsp; From Your Wallet</strong></li>\r\n<li>You Have to Maintain&nbsp; Rs.100/- Minimum as Minimum Balance in Your Wallet . Only Then You Will be Able to do Bidding and The Lead Generation will Take Place.</li>\r\n<li><strong>Add on Keyword Rs.2000 &amp; Areas Rs.1500 Chargeable<br /><br /></strong><strong>Basic Setup Charge Includes the Following Works</strong></li>\r\n<li>Set up your Service Outlet &amp; Directory Listing Including Contact Information on the Services Portal</li>\r\n<li>100% Control by the Lead Management, Service Outlets with Our CMS<strong>&nbsp;</strong>that You Can Regulate Each &amp; Everything by Yourself.</li>\r\n<li>Upon the Cessation of the Services &amp; Directory Listing Outlets, the Contract is Void. With removal of the Services &amp; Directory Outlets, the Contract is Further Transferred to the New Premises with all Right and Obligation, Changes Shall be Notified Immediately</li>\r\n<li><strong>Top-up&nbsp;</strong>Your Wallet Amount Online Also.</li>\r\n</ol>\r\n<p><strong>Terms &amp; Condition:</strong></p>\r\n<ol>\r\n<li>Degradation or Upgradation of any Bidding Outlets Automatically it will be Activated Within Few Mins.</li>\r\n<li>If You have Any Changes you Can Feel Free to Contact Our Customer Care + 73055 88891</li>\r\n<li>Support Timing Morning 10.00 am to 6.30 pm Only</li>\r\n<li style=\"list-style-type: none;\">&nbsp;</li>\r\n</ol>', 10, 2, 1000, 750, '', 5, 3, 10000, 100, '75'),
(3, 'ADVANCE COMBO OFFER                       ', '22000', 365, '<p><strong>VENDOR PACKAGES:</strong></p>\r\n<p><strong>ADVANCE COMBO OFFER<br />CALLINFO</strong> will Provide the Online Facility to the Outlets Vendor Services with the Following Terms and Conditions.</p>\r\n<ol>\r\n<li>For the use of this Service fee of 365 Days (Trial Pack)<strong>22000</strong>/- Inclusive Services Tax18%</li>\r\n<li>If U Need To Add - On Area For Your&nbsp; Services (or) Add -On Keyword , Extra Charges Will Apply.</li>\r\n<li>In This <strong>DIAMOND</strong> Package , You Get <strong>Free&nbsp; Listing of 5 Keywords +</strong> <strong>20 Areas as&nbsp; Default .</strong></li>\r\n<li>Directory Listing Keyword Wise Wallet Addon&nbsp; Rs.22000 /- In This Packages <strong>Per Lead </strong>you get&nbsp; <strong>Rs.100/- Debited&nbsp; From Your Wallet</strong></li>\r\n<li>You have to Maintain Rs.100/-as Minimum Balance in Your Wallet , Only Then You Will Be Able to do Bidding and The Lead Generation will Take Place.&nbsp;</li>\r\n<li><strong>Add on Keyword Rs.1000 &amp; Areas Rs.750 Chargeable</strong><br /><br /><strong>Basic Setup Charge Includes the Following Works</strong></li>\r\n<li>Set up your Service Outlet &amp; Directory Listing Including Contact Information on the Services Portal</li>\r\n<li>100% Control by the Lead Management, Service Outlets with Our CMS<strong>&nbsp;</strong>that You Can Regulate Each &amp; Everything by Yourself.</li>\r\n<li>Upon the Cessation of the Services &amp; Directory Listing Outlets, the Contract is Void. With removal of the Services &amp; Directory Outlets, the Contract is Further Transferred to the New Premises with all Right and Obligation, Changes Shall be Notified Immediately</li>\r\n<li>You Can<strong> Top-up </strong>Your Wallet Amount&nbsp; Through Online Also.</li>\r\n</ol>\r\n<p><strong>Terms &amp; Condition:</strong></p>\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li style=\"list-style-type: none;\">\r\n<ol>\r\n<li>Degradation or Upgradation of any Bidding Outlets Automatically it will be Activated Within Few Mins.</li>\r\n<li>If You have Any Changes you Can Feel Free to Contact Our Customer Care + 73055 88891</li>\r\n<li>Support Timing Morning 10.00 am to 6.30 pm Only</li>\r\n</ol>\r\n</li>\r\n</ol>\r\n</li>\r\n</ol>', 10, 10, 1000, 750, '', 20, 5, 22000, 100, '100');
