INSERT INTO `comman_messages` (`message_id`, `comman_messages`, `type`, `status`) VALUES
(2, ' வாடிக்கையாளார்கள்  போக்குவண்டி தேவை விபரங்களை தெரிந்து கொள்ள மேலுள்ள ஸ்க்ரோலிங் ஐ அடிக்கடி பார்வையிடவும். அல்லது மெனுவில் பார்வையிடவும்.', 1, 0),
(4, 'வாடகை வண்டிகளை தேட கீழுள்ள பட்டன் ஐ கிளிக் செய்து தேடவும். வாடகை வண்டி தேவையை மெனுவில் Customer Vehicle Requirement - ல் பதிவு செய்யவும் ', 0, 1),
(5, 'டிரைவர் நண்பர்கள் தங்களது வண்டியின் Expiry Date உறுதி செய்ய Registered Vehicle List இல் பார்க்கவும் ', 1, 1),
(6, 'ஆம்புலன்ஸ், ஸ்பாட் பஞ்சர், ஸ்பாட் மெக்கானிக், வாடகை இயந்திரங்களுக்கு தற்பொழுது கட்டணம் இல்லை.', 0, 0),
(7, 'எச்சரிக்கை... டிரைவர் நண்பர்களே... யாராவது Material Packing தொகையை கேட்டால் கொடுக்க வேண்டாம்.', 0, 1),
(8, 'எச்சரிக்கை... டிரைவர் நண்பர்களே... யாராவது Material Packing தொகையை கேட்டால் கொடுக்க வேண்டாம்.', 1, 1);
