INSERT INTO `membership` (`mid`, `title`, `description`, `referal_script`, `referal_script_title`, `video`, `price`, `level1_com`, `level2_com`, `purchase_1`, `purchase_2`, `renew_amount`, `ex_days`, `date`, `re_purches_pre`) VALUES
(1, 'Basic                                                                                         ', '<p>வியாபார சொந்தங்கள் அனைவருக்கும் வணக்கம்!</p>\r\n<p>💐 BUSINESS OPPORTUNITY</p>\r\n<p>Register FREE.. START SHOPPING All Product get SPL Discount.. Become a Members Get More Benefit...</p>\r\n<p>புது முயற்சி, புத்தம் புதிய மேடை, உங்களுக்காகவே <br />உங்கள் தொழிலுக்காகவே</p>\r\n<p>🤝 வேலை வாய்ப்பு! தொழில் வாய்ப்பு! வருமான வாய்ப்பு!! பகுதி/ஓய்வு/முழு நேரமாக பணி புரியும் வாய்ப்பு!!!</p>\r\n<p>🤝இந்த www.Callinfo.in பிசினஸில் Rs.299/- ரூபாய் கொடுத்து Membership ஆக்டிவேட் செய்தால் போதும்</p>\r\n<p>இன்று உலக அளவில் மிகப்பெரிய அளவில் நடைபெறும் Referral Earning வியாபாரத்தில் இணைந்து எளிய வியாபாரத்தின் மூலம் சம்பாதிக்கலாம்.</p>\r\n<p>INCOME 4 WAY BENIFITS</p>\r\n<p>👍 1) நம் வீட்டிற்கு தேவையான FMCG பொருட்களை M.R.P விலையில் DISCOUNT வாங்குவதன் மூலம் மாதம் ரூ.1000 முதல் ரூ.2000 அதற்கு மேலும் சேமிக்க வாய்ப்பு.!</p>\r\n<p>👍 2) மறுவிற்பனை மூலம் வருமானம் வாய்ப்பு ஈட்டிடலாம் ஒர் அறிய வாய்ப்பு</p>\r\n<p>👍 3) மற்றவர்களை அறிமுகம் செய்யும் நபர்கள் முலம் 5% + அறிமுகம் செய்த நபர்கள் பொருட்களை வாங்குவதன் முலம் 10% வருமானம் வாய்ப்பு ஈட்டிடலாம்.</p>\r\n<p>👍 4) அறிமுகம் செய்த நபர்கள் மற்றவர்களை அறிமுகம் செய்வதின் முலம் 2% + அறிமுகம் செய்த நபர்கள் பொருட்களை வாங்குவதன் மூலம் 2% வருமானம் வாய்ப்பு ஈட்டிடலாம்.</p>\r\n<p>👍 பயிற்சி இலவசம் CHENNAI சேர்ந்த நபர்களுக்கு முன்னுரிமை</p>\r\n<p>👉🏻 REFFERAL EARNING முளம் பணம் சம்பாதிக்களம் நீங்கள் இந்த கீழே இருக்கும் linkல் சென்று Registration பண்ணிக்கொள்ளுங்கள் <br /><br />தொடர்புக்கு :-<br />👇👇👇 SARAVANA KUMAR<br />📞 9962516035<br /><br />✋ அறிய வாய்ப்பை தவற விடாதீர்கள்</p>', 'வியாபார சொந்தங்கள் அனைவருக்கும் வணக்கம்!  💐புது முயற்சி, புத்தம் புதிய மேடை, உங்களுக்காகவே உங்கள் தொழிலுக்காகவே  🤝 வேலை வாய்ப்பு! தொழில் வாய்ப்பு! வருமான வாய்ப்பு!! பகுதி/ஓய்வு/முழு நேரமாக பணி புரியும் வாய்ப்பு!!!', 'Membership', '<iframe width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/m8WfmgZLED4\" title=\"YouTube video player\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\" allowfullscreen></iframe>', '20', '5', '3', '5', '3', '299', '365', '2021-12-21', 10);
